INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('knowledge-root', 'Start here', '# Start here{{~nyyon-nl~}}{{~nyyon-nl~}}Your own AI command center. **Nyo**, the assistant at the center, plus modules that arrive as **plugins** — installable, removable, tradeable between systems.{{~nyyon-nl~}}{{~nyyon-nl~}}## What lives here{{~nyyon-nl~}}- **Plugins**: the modules in the sidebar. Each ships its tools, its page, and its own knowledge docs (the plugin-* entries in this tree). Manage them on the Plugins page.{{~nyyon-nl~}}- **Nyo**: chats, plans, and drives every installed tool. The docs in this tree are its memory — edit a doc and behavior changes, no code involved.{{~nyyon-nl~}}- **System pages**: Knowledge (this tree), Plugins, Activity (everything that happened), Expand build, Settings.{{~nyyon-nl~}}{{~nyyon-nl~}}## Where to start{{~nyyon-nl~}}- New here? Open the **Daily Planner** and say "plan my day".{{~nyyon-nl~}}- Connecting services (model key, WhatsApp, anything external): **Settings → Connections**.{{~nyyon-nl~}}- Something looks off: **Activity** shows every mutation; the dot bottom-left is system health.', 'global', NULL, 1788458993000, NULL);
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('about', 'About this install', '# About this install{{~nyyon-nl~}}{{~nyyon-nl~}}An AI command center you own. It runs as one self-contained install: the app, its database, and its scheduled work all live together, and nothing leaves unless you connect it.{{~nyyon-nl~}}{{~nyyon-nl~}}- **Nyo** is the center: one assistant across every module, with tiered models (fast / standard / deep).{{~nyyon-nl~}}- **Modules are plugins.** Each is a sealed capability: its own tools, page, tables and knowledge. Install, remove, export, import — the system stays coherent.{{~nyyon-nl~}}- **Tools are the verbs; modules are the sentences.** Nyo knows every verb of every installed module.{{~nyyon-nl~}}- **Knowledge is the control surface.** Rules, voices and thresholds live as editable docs here, not as code.', 'global', NULL, 1788458993000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('brand', 'Brand — voice, positioning, visual', '# Brand{{~nyyon-nl~}}{{~nyyon-nl~}}Fill this branch in for your company. Nyo and the content writers read this tree before drafting anything public, so keep it current: who you are, your positioning one-liner, and how you sound.{{~nyyon-nl~}}{{~nyyon-nl~}}## Positioning one-liner{{~nyyon-nl~}}Write yours here. One sentence a stranger could repeat.{{~nyyon-nl~}}{{~nyyon-nl~}}## Voice{{~nyyon-nl~}}See `brand-voice` for the full writing rules. Keep them short and operational: what to avoid, what a good sentence looks like.{{~nyyon-nl~}}{{~nyyon-nl~}}## Visual language{{~nyyon-nl~}}Describe your palette, typography, and layout conventions here so generated assets stay consistent.{{~nyyon-nl~}}{{~nyyon-nl~}}## CTA destination{{~nyyon-nl~}}Every "Book a call" surface on the public site is routed through `web-public/src/lib/cta.ts`, so swapping the scheduling link is a one-line change.', 'global', NULL, 1788458993000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('module-nyo', 'Module · Nyo — the chatbot', '# Nyo{{~nyyon-nl~}}{{~nyyon-nl~}}The chatbot at the center. Full-screen page (`web/src/pages/Nyo.tsx`) plus a side drawer that shares the same `ChatProvider` state.{{~nyyon-nl~}}{{~nyyon-nl~}}## Today{{~nyyon-nl~}}- SSE streaming. Tool-use loop with 8 hops max.{{~nyyon-nl~}}- Provider-agnostic via `callLLM` → Anthropic or OpenAI.{{~nyyon-nl~}}- 20+ tools: knowledge CRUD, modules/tools/roadmap registry, content blocks, feature flags, WhatsApp send/reply/image/document/react, LinkedIn DMs.{{~nyyon-nl~}}- Reads the channels knowledge docs before any WhatsApp work (auto-prime → /start → poll → send).{{~nyyon-nl~}}{{~nyyon-nl~}}## Where it lives{{~nyyon-nl~}}- Worker handler: `workers/api/src/chat/index.js`{{~nyyon-nl~}}- Tools registry: `workers/api/src/chat/tools.js`{{~nyyon-nl~}}- UI: `web/src/pages/Nyo.tsx`, `web/src/components/ChatDrawer.tsx`, `web/src/lib/chat.tsx`{{~nyyon-nl~}}{{~nyyon-nl~}}## Provider switch{{~nyyon-nl~}}Set in `workers/api/.dev.vars`:{{~nyyon-nl~}}- `LLM_PROVIDER=openai|anthropic`{{~nyyon-nl~}}- `LLM_MODEL=...` (optional override){{~nyyon-nl~}}- `OPENAI_API_KEY` or `ANTHROPIC_API_KEY`{{~nyyon-nl~}}{{~nyyon-nl~}}Health probe at `/api/nyo/brain` reports the active provider + model + key-set status.{{~nyyon-nl~}}{{~nyyon-nl~}}## Prompts{{~nyyon-nl~}}System prompts for individual tools live in knowledge docs so they can be edited without a deploy. Example: create a `prompt-wa-reply` doc to override the WhatsApp reply writer''s default prompt.{{~nyyon-nl~}}{{~nyyon-nl~}}## How to add a tool{{~nyyon-nl~}}Edit `workers/api/src/chat/tools.js`. Each tool is `{ name, description, input_schema, handler(env, input) }`. The chat loop wires it automatically.{{~nyyon-nl~}}{{~nyyon-nl~}}## The setup interview{{~nyyon-nl~}}The interview is a DEDICATED flow, not a plain-chat improvisation: it opens from the "finish with Nyo" banner (or the setup screen) and writes the canonical voice documents. If the operator asks you to interview them in this chat, do not improvise one — tell them to press the banner, which opens the real thing.', 'module', 'nyo', 1788458993000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('system-knowledge', 'System · Knowledge — this tree', '# Knowledge{{~nyyon-nl~}}{{~nyyon-nl~}}The thing you''re reading right now. A tree of markdown docs that grounds Nyo, orients new collaborators, and survives across sessions.{{~nyyon-nl~}}{{~nyyon-nl~}}## Today{{~nyyon-nl~}}- D1 table `knowledge_docs` with columns: slug, title, body, scope (global/module), module, parent_slug, updated_at.{{~nyyon-nl~}}- Tree shape via `parent_slug`. Root is `knowledge-root` with `parent_slug = NULL`.{{~nyyon-nl~}}- Routes: `GET /api/knowledge`, `/:slug`, `/:slug/path` (breadcrumb chain), `PUT /:slug`, `DELETE /:slug`.{{~nyyon-nl~}}- UI: `web/src/pages/Knowledge.tsx`. Sidebar = tree view. Reading pane shows breadcrumb above the body.{{~nyyon-nl~}}- Nyo tools: `list_knowledge`, `read_knowledge`, `write_knowledge`, `delete_knowledge`. All accept `parent_slug` so Nyo can reshape the tree from chat.{{~nyyon-nl~}}{{~nyyon-nl~}}## Rules{{~nyyon-nl~}}- Every doc must have a parent except the root. Orphans surface in the UI under "Unparented".{{~nyyon-nl~}}- Delete promotes children to root (no silent cascade — caller can re-parent).{{~nyyon-nl~}}- Module-scoped docs (`scope=''module''`) get an extra `module` tag for filtering.{{~nyyon-nl~}}{{~nyyon-nl~}}## See also{{~nyyon-nl~}}- `how-knowledge-works` — older rationale + writing tips', 'global', NULL, 1788458993000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('system-activity', 'System · Activity log', '# Activity{{~nyyon-nl~}}{{~nyyon-nl~}}Every significant thing that happens lands in the `events` table — knowledge edits, contact updates, digest generations, sends, conversions, content edits. The Activity page is the unfiltered tail.{{~nyyon-nl~}}{{~nyyon-nl~}}## Today{{~nyyon-nl~}}- Routes: `/api/events?limit=N`.{{~nyyon-nl~}}- Page: `web/src/pages/Activity.tsx` — reverse-chronological feed with kind filter.{{~nyyon-nl~}}- `logEvent({ kind, actor, payload })` is called throughout the worker code.{{~nyyon-nl~}}{{~nyyon-nl~}}## Common event kinds{{~nyyon-nl~}}- `digest_generated` — used by the digest "updated Nm ago" subtitle{{~nyyon-nl~}}- `digest_action` — operator clicked Approve/Dismiss/Wishlist on a digest item{{~nyyon-nl~}}- `wa_sent`, `wa_reacted`, `wa_backfill`{{~nyyon-nl~}}- `contact_updated`, `contact_added`, `contact_deleted`{{~nyyon-nl~}}- `content_updated`, `blog_post_updated`{{~nyyon-nl~}}- `knowledge_updated`, `knowledge_deleted`', 'global', NULL, 1788458993000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('system-settings', 'System · Settings', '# Settings{{~nyyon-nl~}}{{~nyyon-nl~}}Operator preferences and feature flags. Three tabs:{{~nyyon-nl~}}- **Appearance** — light / dark / system theme.{{~nyyon-nl~}}- **Sidebar modules** — toggle which surface slugs appear in the sidebar (per-operator preference, stored in localStorage).{{~nyyon-nl~}}- **Feature flags** — D1-backed (`feature_flags` table) toggles that gate features for Nyo + the UI.{{~nyyon-nl~}}{{~nyyon-nl~}}## Where it lives{{~nyyon-nl~}}- Schema: `db/schema.sql` (`feature_flags`).{{~nyyon-nl~}}- Routes: `/api/flags`, `/:key`.{{~nyyon-nl~}}- Page: `web/src/pages/Settings.tsx`.{{~nyyon-nl~}}- Theme helpers: `web/src/lib/theme.ts`.', 'global', NULL, 1788458993000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('expand-build-prompt', 'Expand build — the coding-agent prompt', '# Expand this system{{~nyyon-nl~}}{{~nyyon-nl~}}You are a coding agent working on a nyyon: a self-contained AI command center the operator owns. One repo holds everything: a Cloudflare Worker API, a React SPA, a D1 database, and installable plugins. The checkout IS the install. Work inside it, in its style, and leave every layer where it belongs.{{~nyyon-nl~}}{{~nyyon-nl~}}## 0. Where you are{{~nyyon-nl~}}{{~nyyon-nl~}}The repo root is: {{REPO}}{{~nyyon-nl~}}{{~nyyon-nl~}}Key paths:{{~nyyon-nl~}}- workers/api/src : the Worker (API, chat engine, gateways, tools, libs){{~nyyon-nl~}}- web/src : the SPA (pages, components; plugin pages materialize into web/src/plugins/){{~nyyon-nl~}}- plugins/ : plugin packs (source of truth for every module){{~nyyon-nl~}}- db/migrations/ : append-only SQL migrations{{~nyyon-nl~}}- scripts/ : pack-plugin.mjs, materialize-bundled.mjs, bundle-schema.mjs{{~nyyon-nl~}}- CLAUDE.md : repo rules. Read it first. It wins over this prompt where they differ.{{~nyyon-nl~}}{{~nyyon-nl~}}## 1. Connect to Cloudflare{{~nyyon-nl~}}{{~nyyon-nl~}}1. npm install -g wrangler{{~nyyon-nl~}}2. wrangler login  (opens the browser; the operator approves){{~nyyon-nl~}}3. wrangler whoami  (verify the right account){{~nyyon-nl~}}4. Local dev: run the dev server the repo way (see CLAUDE.md / package.json scripts). The Worker runs with a local D1 under workers/api/.wrangler/state; deleting that directory resets the install.{{~nyyon-nl~}}5. Deploy: from workers/api, wrangler deploy. Database: wrangler d1 create <name> once, then wrangler d1 migrations apply. Secrets: wrangler secret put <NAME>. Model keys the operator pastes in Settings live DB-first in gateway_config; env vars are only the fallback.{{~nyyon-nl~}}{{~nyyon-nl~}}## 2. Get nyyon-lite{{~nyyon-nl~}}{{~nyyon-nl~}}The framework is this repo plus the rules below. To start a fresh system instead of extending this one: git clone https://github.com/LevNyyon/nyyon.git and strip the packs you do not need from plugins/.{{~nyyon-nl~}}{{~nyyon-nl~}}## 3. The framework: five layers, strict{{~nyyon-nl~}}{{~nyyon-nl~}}Every capability decomposes into exactly these layers. Put each change in its layer and nowhere else.{{~nyyon-nl~}}{{~nyyon-nl~}}1. GATEWAY: the boundary to ONE external service (one file, one service, no reasoning, no business logic). It translates in and out, holds the service''s protocol quirks, and is the only place that touches the network for that service. Register it with modes and, when generic, a capability tag so the host discovers it by capability, never by name.{{~nyyon-nl~}}2. TOOL: one job with a name, a description a model can act on, and a strict input schema. Tools reach services only through gateways, live in one shared pool, and return {ok, ...} or {ok:false, error}. No tool calls another tool''s internals.{{~nyyon-nl~}}3. WORKFLOW: an ordered list of existing tools. No new logic inside; if you need logic, you are missing a tool.{{~nyyon-nl~}}4. MODULE: a product area with a UI page. Every module ships a visualization; a module without a screen is a library, not a module.{{~nyyon-nl~}}5. KNOWLEDGE: editable rules, prompts, thresholds, and voices as markdown docs in the knowledge tree. Behavior an operator might tune goes here, never hardcoded. Docs win over baked defaults; code falls back if a doc is missing.{{~nyyon-nl~}}{{~nyyon-nl~}}Guardrails, non-negotiable:{{~nyyon-nl~}}- Gateways never reason. Tools never speak to services directly. Workflows never branch.{{~nyyon-nl~}}- Everything that mutates logs to the activity bus (events table) with actor and payload.{{~nyyon-nl~}}- Files are written whole; no append-patching of source files.{{~nyyon-nl~}}- Migrations are append-only; never edit an applied migration.{{~nyyon-nl~}}- Never edit generated files (workers/api/src/plugins/index.js, web/src/plugins/, workers/api/src/generated/): regenerate them with the scripts.{{~nyyon-nl~}}- All copy the system composes obeys the dont-sound-ai knowledge doc: it is welded into every prompt; do not remove the weld.{{~nyyon-nl~}}{{~nyyon-nl~}}## 4. Build new things as PLUGINS{{~nyyon-nl~}}{{~nyyon-nl~}}A module you add ships as a plugin pack in plugins/<name>/:{{~nyyon-nl~}}- manifest.json (nyyon_plugin: 2): name, version, description, requires (gateways it consumes, tables it owns), provides (gateways, tools, workflows, knowledge, surfaces).{{~nyyon-nl~}}- Namespaces are law: tables plugin_<name>_* (underscores), knowledge slugs plugin-<name>-*, gateways one per external service.{{~nyyon-nl~}}- Pack code is sealed: no imports from the host; each file receives a capability object (api.db scoped to your tables, api.gateway bound to declared gateways, api.knowledge for declared docs, api.log). Cross-pack reads are declared in requires and must degrade gracefully when the other pack is absent.{{~nyyon-nl~}}- A surface is a React page (page_file) plus optional files; it talks only to its own plugin''s tools over /api/plugins/<name>/invoke/<tool>.{{~nyyon-nl~}}- Validate and package: node scripts/pack-plugin.mjs plugins/<name> (JSON), or zip the folder. Install through the Plugins page (upload zip or paste manifest); the applier binds, materializes, and activates it live.{{~nyyon-nl~}}- Bundled-by-default packs are listed by presence in plugins/; after changing any, run node scripts/materialize-bundled.mjs and rebuild the web app.{{~nyyon-nl~}}{{~nyyon-nl~}}## 5. How to work{{~nyyon-nl~}}{{~nyyon-nl~}}- Before finishing any change, review it against the guardrails above.{{~nyyon-nl~}}- Test against the running install; prove a tool by invoking it, not by reading it.{{~nyyon-nl~}}- When a rule or prompt should be operator-tunable, put it in a knowledge doc and read it at runtime with a baked fallback.{{~nyyon-nl~}}- Report what you did in plain words: what changed, where, and how you verified it.{{~nyyon-nl~}}', 'global', NULL, 1788370000000, 'knowledge-root');
INSERT OR IGNORE INTO "knowledge_docs" ("slug", "title", "body", "scope", "module", "updated_at", "parent_slug") VALUES ('how-knowledge-works', 'How Knowledge Works', '# How Knowledge Works{{~nyyon-nl~}}{{~nyyon-nl~}}Every doc here is read + written by Nyo. He uses ``list_knowledge`` to enumerate slugs, ``read_knowledge`` to load one, and ``write_knowledge`` to capture decisions.{{~nyyon-nl~}}{{~nyyon-nl~}}**Scope rules**{{~nyyon-nl~}}- ``global`` — system-wide facts, principles, definitions.{{~nyyon-nl~}}- ``module`` — scoped to one module slug (e.g. blog, outreach).{{~nyyon-nl~}}{{~nyyon-nl~}}**Slug convention**: lowercase-with-dashes. Stable identifier, never rename — write a new doc and link instead.', 'global', NULL, 1788458993000, 'system-knowledge');
