INSERT OR IGNORE INTO "workflows" ("slug", "name", "description", "trigger", "steps", "source", "status", "created_at", "updated_at", "created_by", "updated_by") VALUES ('aeo-daily-writer', 'AEO daily writer', 'Each day at 06:00 UTC, pick the highest-priority pending AEO question, read Nyyon brand voice + AEO playbook + recent posts, draft an article via OpenAI gpt-5.5, publish straight to blog_posts, and mark the question published. Hardcoded today in lib/aeo-writer.js — surfaced here for visibility.', '{"kind":"cron","schedule":"0 6 * * *","timezone":"UTC"}', '[{"type":"db","name":"Pick next pending question","action":"nextPendingAeoQuestion","out":"question"},{"type":"db","name":"Read brand voice + playbook + recent posts","action":"loadAeoContext","out":"context"},{"type":"llm","name":"Draft article in Nyyon voice","model":"openai/gpt-5.5","prompt":"build via buildUserPrompt() in aeo-writer.js","out":"draft"},{"type":"db","name":"Ensure slug uniqueness","action":"ensureUniqueSlug","out":"slug"},{"type":"tool","name":"Publish to blog","tool":"write_blog_post","input":"draft fields, published=1"},{"type":"db","name":"Mark question published","action":"markAeoQuestionPublished"}]', 'system', 'active', 1788458993000, 1788458993000, 'system-seed', NULL);
INSERT OR IGNORE INTO "workflows" ("slug", "name", "description", "trigger", "steps", "source", "status", "created_at", "updated_at", "created_by", "updated_by") VALUES ('blog-to-calendar-mirror', 'Blog → Calendar mirror', 'Every time a blog post is saved with published=1, upsert a matching calendar_event (kind=blog_publish, all_day, status=done if past / confirmed if future). Hardcoded today as a hook inside writeBlogPost — surfaced here for visibility.', '{"kind":"event","event":"blog_post_published"}', '[{"type":"tool","name":"Upsert calendar event","tool":"write_calendar_event","input":"{kind:blog_publish, title, description=excerpt, starts_at=published_at, all_day:true, source:blog, source_ref:slug, link_url:/blog/<slug>}"}]', 'system', 'active', 1788458993000, 1788458993000, 'system-seed', NULL);
